import "server-only";
import { and, desc, eq, gt, gte, isNull, or, sql } from "drizzle-orm";
import { configuredProviders } from "@/lib/ai/providers";
import { db, schema } from "@/lib/db";
import { getSettings, listIntegrations } from "@/lib/db/queries/settings";
import { env } from "@/lib/env";
import { mapSpanNode, NODES, type FlowSpan, type NodeBase, type NodeId } from "./model";

/** Spans are metadata only (labels + counts). Labels are generated by Cowork, never copied from external content. */
function toFlowSpan(s: typeof schema.traceSpans.$inferSelect): FlowSpan {
  return {
    id: s.id,
    runId: s.runId,
    runKind: s.runKind,
    trigger: s.trigger,
    node: s.node,
    label: s.label,
    status: s.status as FlowSpan["status"],
    meta: s.meta,
    startedAt: s.startedAt.toISOString(),
    endedAt: s.endedAt?.toISOString() ?? null,
  };
}

/** Spans that started OR ended after the cursor (so running → ok updates arrive). */
export async function flowEvents(userId: string, opts: { since?: Date; runId?: string; limit?: number }) {
  const limit = Math.min(opts.limit ?? 200, 500);
  const conds = [eq(schema.traceSpans.userId, userId)];
  if (opts.runId) conds.push(eq(schema.traceSpans.runId, opts.runId));
  else {
    const since = opts.since ?? new Date(Date.now() - 10 * 60_000);
    conds.push(or(gt(schema.traceSpans.startedAt, since), gt(schema.traceSpans.endedAt, since))!);
  }
  const rows = await db().select().from(schema.traceSpans).where(and(...conds)).orderBy(desc(schema.traceSpans.startedAt)).limit(limit);
  return rows.reverse().map(toFlowSpan);
}

/** Recent runs for the Flow page. */
export async function recentRuns(userId: string, limit = 30) {
  const rows = await db()
    .select({
      runId: schema.traceSpans.runId,
      runKind: sql<string>`min(${schema.traceSpans.runKind})`,
      trigger: sql<string>`min(${schema.traceSpans.trigger})`,
      startedAt: sql<string>`min(${schema.traceSpans.startedAt})`,
      endedAt: sql<string | null>`max(${schema.traceSpans.endedAt})`,
      steps: sql<number>`count(*)::int`,
      errors: sql<number>`count(*) filter (where ${schema.traceSpans.status} = 'error')::int`,
      running: sql<number>`count(*) filter (where ${schema.traceSpans.status} = 'running')::int`,
    })
    .from(schema.traceSpans)
    .where(eq(schema.traceSpans.userId, userId))
    .groupBy(schema.traceSpans.runId)
    .orderBy(desc(sql`min(${schema.traceSpans.startedAt})`))
    .limit(limit);
  return rows.map((r) => ({ ...r, startedAt: new Date(r.startedAt).toISOString(), endedAt: r.endedAt ? new Date(r.endedAt).toISOString() : null }));
}

const cache = new Map<string, { at: number; value: Record<NodeId, NodeBase> }>();
const CACHE_MS = 4_000;

/**
 * Per-node connection/enable state, 1-hour call and error counts, permissions.
 * "connected" and "enabled" come from real config and the owner's switches.
 */
export async function flowStatus(userId: string): Promise<Record<NodeId, NodeBase>> {
  const hit = cache.get(userId);
  if (hit && Date.now() - hit.at < CACHE_MS) return hit.value;

  const [s, integrations, sources, tokens, pending, automations, hour] = await Promise.all([
    getSettings(userId),
    listIntegrations(userId),
    db().select({ type: schema.knowledgeSources.type, included: schema.knowledgeSources.included }).from(schema.knowledgeSources).where(eq(schema.knowledgeSources.userId, userId)),
    db()
      .select({ scopes: schema.apiTokens.scopes })
      .from(schema.apiTokens)
      .where(and(eq(schema.apiTokens.userId, userId), isNull(schema.apiTokens.revokedAt), or(isNull(schema.apiTokens.expiresAt), gt(schema.apiTokens.expiresAt, new Date())))),
    db().select({ n: sql<number>`count(*)::int` }).from(schema.proposals).where(and(eq(schema.proposals.userId, userId), eq(schema.proposals.status, "pending"))),
    db().select({ n: sql<number>`count(*)::int` }).from(schema.automations).where(eq(schema.automations.userId, userId)),
    db()
      .select({ node: schema.traceSpans.node, status: schema.traceSpans.status, startedAt: schema.traceSpans.startedAt, endedAt: schema.traceSpans.endedAt })
      .from(schema.traceSpans)
      .where(and(eq(schema.traceSpans.userId, userId), gte(schema.traceSpans.startedAt, new Date(Date.now() - 3_600_000))))
      .orderBy(desc(schema.traceSpans.startedAt))
      .limit(3000),
  ]);

  const conn = (p: string) => integrations.some((i) => i.provider === p && i.status === "connected");
  const src = (t: string) => sources.find((x) => x.type === t);
  const google = conn("google");
  const ai = configuredProviders().length > 0;
  const caps = s.agent.capabilities;
  const claudeWrite = tokens.some((t) => t.scopes.some((x) => x.endsWith(":write")));

  const shape: Record<NodeId, Pick<NodeBase, "connected" | "enabled" | "permissions"> & { pending?: number }> = {
    "input:text": { connected: true, enabled: true, permissions: "n/a" },
    "input:voice": { connected: true, enabled: true, permissions: "n/a" },
    "input:claude": { connected: tokens.length > 0, enabled: true, permissions: claudeWrite ? "read/write" : "read-only" },
    "input:automation": { connected: (automations[0]?.n ?? 0) > 0, enabled: !s.automationsPaused, permissions: "n/a" },
    agent: { connected: ai, enabled: true, permissions: "read-only" },
    "model:fast": { connected: ai, enabled: true, permissions: "n/a" },
    "model:smart": { connected: ai, enabled: true, permissions: "n/a" },
    "model:embed": { connected: Boolean(env().EMBEDDING_MODEL) && ai, enabled: true, permissions: "n/a" },
    gmail: { connected: google, enabled: caps.readEmail, permissions: "read-only" },
    calendar: { connected: google, enabled: true, permissions: "read-only" },
    tasks: { connected: true, enabled: caps.manageTasks, permissions: "read/write" },
    knowledge: { connected: true, enabled: caps.searchKnowledge, permissions: "read-only" },
    news: { connected: true, enabled: s.newsTopics.length > 0, permissions: "read-only" },
    drive: { connected: google && Boolean(src("drive")), enabled: src("drive")?.included ?? true, permissions: "read-only" },
    notion: { connected: conn("notion") && Boolean(src("notion")), enabled: src("notion")?.included ?? true, permissions: "read-only" },
    slack: { connected: conn("slack") && Boolean(src("slack")), enabled: src("slack")?.included ?? true, permissions: "read-only" },
    github: { connected: conn("github") && Boolean(src("github")), enabled: src("github")?.included ?? true, permissions: "read-only" },
    approval: { connected: true, enabled: true, permissions: "n/a", pending: pending[0]?.n ?? 0 },
    "output:draft": { connected: google, enabled: caps.createDrafts, permissions: "drafts only" },
    "output:tasks": { connected: true, enabled: caps.manageTasks, permissions: "read/write" },
    "output:content": { connected: true, enabled: true, permissions: "drafts only" },
    "output:notes": { connected: true, enabled: true, permissions: "read/write" },
    "output:notify": { connected: true, enabled: s.notifyInApp || s.notifyEmail || s.notifyTelegram, permissions: "notify only" },
  };

  const stats = new Map<NodeId, { calls: number; errors: number; last: number; lastErr: number }>();
  for (const h of hour) {
    const id = mapSpanNode(h.node);
    if (!id) continue;
    const st = stats.get(id) ?? { calls: 0, errors: 0, last: 0, lastErr: 0 };
    const at = (h.endedAt ?? h.startedAt).getTime();
    st.calls++;
    st.last = Math.max(st.last, at);
    if (h.status === "error") {
      st.errors++;
      st.lastErr = Math.max(st.lastErr, at);
    }
    stats.set(id, st);
  }

  const value: Record<NodeId, NodeBase> = {};
  for (const n of NODES) {
    const sh = shape[n.id]!;
    const st = stats.get(n.id);
    value[n.id] = {
      connected: sh.connected,
      enabled: sh.enabled,
      permissions: sh.permissions,
      pending: sh.pending,
      calls1h: st?.calls ?? 0,
      errors1h: st?.errors ?? 0,
      lastActivityAt: st?.last ? new Date(st.last).toISOString() : null,
      lastErrorAt: st?.lastErr ? new Date(st.lastErr).toISOString() : null,
    };
  }
  cache.set(userId, { at: Date.now(), value });
  return value;
}

export function invalidateFlowStatus(userId: string) {
  cache.delete(userId);
}
